-- Baseline demo seed: a small synthetic org (see OSS_READINESS_PLAN.md /
-- the conway commit history for why this replaced real org data). Not a
-- goose migration — applied at boot when CONWAY_SEED_BASELINE is unset or
-- true, and safe to re-run by hand any time (ON CONFLICT DO NOTHING).

-- The roster snapshots re-associate with (see rostersui.js) — public so it's
-- visible to every manager, not just its ('') owner.
  'demo-roster', '', 'Demo org roster',
  '[
    {"name":"Atlas","location":"Austin","pairing":true,"devCount":6},
    {"name":"Beacon","location":"Dublin","pairing":true,"devCount":5},
    {"name":"Cascade","location":"Toronto","pairing":true,"devCount":4},
    {"name":"Delta","location":"Remote","pairing":true,"devCount":7},
    {"name":"Ember","location":"Warsaw","pairing":false,"devCount":5},
    {"name":"Fjord","location":"Oslo","pairing":true,"devCount":6},
    {"name":"Granite","location":"Denver","pairing":true,"devCount":8},
    {"name":"Harbor","location":"Singapore","pairing":false,"devCount":4},
    {"name":"Ibis","location":"Remote","pairing":true,"devCount":3},
    {"name":"Juniper","location":"Berlin","pairing":true,"devCount":5}
  ]'::jsonb, true, 1751328000, 1751328000
) ON CONFLICT (id) DO NOTHING;

-- ON CONFLICT DO UPDATE (not DO NOTHING) so upgrading from a pre-roster seed
-- backfills the association on a baseline snapshot that already exists.
  VALUES ('baseline', '', 'Baseline (demo)', 'baseline', 'demo-roster', 1751328000)
  ON CONFLICT (id) DO UPDATE SET roster_id = EXCLUDED.roster_id;

ON CONFLICT (snapshot_id, name) DO NOTHING;

ON CONFLICT (snapshot_id, pod) DO NOTHING;

ON CONFLICT (snapshot_id, from_pod, to_pod) DO NOTHING;

ON CONFLICT (snapshot_id, pod) DO NOTHING;
-- Individual issues + blocking links behind the aggregate stats above:
-- powers the Flow Actions freeze/fever panels, the Org Network edge
-- drill-down, hygiene issue lists, and unassociated-epic detection.
-- Link counts per (from_pod, to_pod) match snapshot_edges exactly.

ON CONFLICT (snapshot_id, key) DO NOTHING;

ON CONFLICT (snapshot_id, blocker_key, blocked_key) DO NOTHING;
